def __init__(self, value: str | typing.Sequence[str]):
    if isinstance(value, str):
        splitter = shlex(value, posix=True)
        splitter.whitespace = ","
        splitter.whitespace_split = True
        self._items = [item.strip() for item in splitter]
    else:
        self._items = list(value)
